// Sum returns the checksum of the represented migration directory.
func (f HashFile) Sum() (string, error) {
	sha := sha256.New()
	for _, h := range f {
		if _, err := sha.Write([]byte(h.N)); err != nil {
			return "", err
		}
		b, err := base64.StdEncoding.DecodeString(h.H)
		if err != nil {
			return "", err
		}
		if _, err := sha.Write(b); err != nil {
			return "", err
		}
	}
	return base64.StdEncoding.EncodeToString(sha.Sum(nil)), nil
}
